import json
import math
import statistics

dates = ["2024-01-02", "2024-01-03", "2024-01-04", "2024-01-05", "2024-01-08", "2024-01-09"]
closes = {
    "A": [100.0, 101.0, 99.5, 100.5, 102.0, 101.0],
    "B": [50.0, 50.5, 50.25, 49.75, 50.0, 51.0],
}
tickers = ["A", "B"]
rets = {t: [math.log(c[i] / c[i - 1]) for i in range(1, len(c))] for t, c in closes.items()}
w = 2
vol = {
    t: [None if i < w else statistics.stdev(r[i - w : i]) * math.sqrt(252) for i in range(len(r))]
    for t, r in rets.items()
}
out = {}
out["prices"] = {"dates": dates, "tickers": tickers, "closes": closes}
out["returns"] = {"base_date": dates[0], "dates": dates[1:], "tickers": tickers, "values": rets}
out["vol"] = {"returns": out["returns"], "window": w, "annualized": True, "values": vol}
summ = {}
dd = {}
for t in tickers:
    r = rets[t]
    ar = 252 * statistics.mean(r)
    av = math.sqrt(252) * statistics.stdev(r)
    summ[t] = {"ticker": t, "ann_return": ar, "ann_vol": av, "sharpe": ar / av if av else 0.0, "last_vol": vol[t][-1]}
    wealth = 1.0
    peak, peak_d = 1.0, dates[0]
    best = (0.0, dates[0])
    for d, x in zip(dates[1:], r):
        wealth *= math.exp(x)
        if wealth > peak:
            peak, peak_d = wealth, d
        depth = wealth / peak - 1
        if depth < best[0]:
            best = (depth, peak_d)
    dd[t] = {"ticker": t, "depth": best[0], "peak_date": best[1]}
out["summary"] = summ
out["dd"] = dd
out["rows"] = [
    {**{k: v for k, v in summ[t].items()}, "max_drawdown": dd[t]["depth"], "peak_date": dd[t]["peak_date"]}
    for t in tickers
]
print(json.dumps(out, indent=1))

